@* Confirmation dialog for revoking an active session *@

@if (Visible)
{
    <div class="modal-backdrop fade show"></div>
    <div class="modal d-block fade show" tabindex="-1" role="dialog">
        <div class="modal-dialog modal-dialog-centered">
            <div class="modal-content">
                <div class="modal-header">
                    <h5 class="modal-title">Revoke Session</h5>
                    <button type="button" class="btn-close" @onclick="Cancel"></button>
                </div>
                <div class="modal-body">
                    <p>
                        Are you sure you want to revoke the session on
                        <strong>@Session?.Device</strong> from <strong>@Session?.Location</strong>?
                    </p>
                    <p class="text-muted small mb-0">This will immediately sign out that device.</p>
                </div>
                <div class="modal-footer">
                    <button class="btn btn-outline-secondary" @onclick="Cancel">Cancel</button>
                    <button class="btn btn-danger" @onclick="Confirm" disabled="@_revoking">
                        @(_revoking ? "Revoking…" : "Revoke")
                    </button>
                </div>
            </div>
        </div>
    </div>
}

@code {
    [Parameter] public bool Visible { get; set; }
    [Parameter] public Services.ActiveSession? Session { get; set; }
    [Parameter] public EventCallback OnConfirmed { get; set; }
    [Parameter] public EventCallback OnCancelled { get; set; }

    private bool _revoking;

    private async Task Confirm()
    {
        _revoking = true;
        await OnConfirmed.InvokeAsync();
        _revoking = false;
    }

    private async Task Cancel() => await OnCancelled.InvokeAsync();
}

@using sv_b932a6f7d888474f98128800617f0fba.Services

<div class="security-section">
    <h4 class="mb-4">Security Settings</h4>

    @if (_settings is null)
    {
        <p class="text-muted">Loading…</p>
        return;
    }

    @* ── Change Password Panel ── *@
    <div class="card mb-4">
        <div class="card-header d-flex justify-content-between align-items-center"
             role="button" @onclick="() => _passwordExpanded = !_passwordExpanded">
            <span class="fw-semibold">Change Password</span>
            <span>@(_passwordExpanded ? "▲" : "▼")</span>
        </div>
        @if (_passwordExpanded)
        {
            <div class="card-body">
                <div class="mb-3">
                    <label class="form-label">Current Password</label>
                    <input class="form-control" type="password" @bind="_currentPassword" />
                </div>
                <div class="mb-3">
                    <label class="form-label">New Password</label>
                    <input class="form-control" type="password" @bind="_newPassword" />
                </div>
                <div class="mb-3">
                    <label class="form-label">Confirm New Password</label>
                    <input class="form-control" type="password" @bind="_confirmPassword" />
                </div>
                <button class="btn btn-primary" @onclick="ChangePasswordAsync" disabled="@_changingPassword">
                    @(_changingPassword ? "Updating…" : "Update Password")
                </button>
                @if (_passwordMessage is not null)
                {
                    <div class="alert @(_passwordError ? "alert-danger" : "alert-success") mt-3">@_passwordMessage</div>
                }
            </div>
        }
    </div>

    @* ── Two-Factor Authentication ── *@
    <div class="card mb-4">
        <div class="card-body d-flex justify-content-between align-items-center">
            <div>
                <h6 class="mb-1">Two-Factor Authentication</h6>
                <span class="badge @(_twoFactorEnabled ? "bg-success" : "bg-secondary")">
                    @(_twoFactorEnabled ? "Enabled" : "Disabled")
                </span>
            </div>
            <div class="form-check form-switch mb-0">
                <input class="form-check-input" type="checkbox" @bind="_twoFactorEnabled" style="transform: scale(1.3);" />
            </div>
        </div>
        @if (_settings.LastPasswordChange.HasValue)
        {
            <div class="card-footer text-muted small">
                Last password change: @_settings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")
            </div>
        }
    </div>

    @* ── Active Sessions ── *@
    <div class="card">
        <div class="card-header fw-semibold">Active Sessions</div>
        <div class="table-responsive">
            <table class="table table-hover mb-0">
                <thead>
                    <tr>
                        <th>Device</th>
                        <th>Location</th>
                        <th>Last Active</th>
                        <th class="text-end">Action</th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var session in _sessions)
                    {
                        var isCurrent = session == _sessions.FirstOrDefault();
                        <tr>
                            <td>@session.Device</td>
                            <td>@session.Location</td>
                            <td>@FormatLastActive(session.LastActive)</td>
                            <td class="text-end">
                                @if (isCurrent)
                                {
                                    <span class="badge bg-info">Current</span>
                                }
                                else
                                {
                                    <button class="btn btn-sm btn-outline-danger"
                                            @onclick="() => PromptRevoke(session)">
                                        Revoke
                                    </button>
                                }
                            </td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>
    </div>
</div>

<RevokeSessionDialog Visible="_revokeDialogVisible"
                     Session="_sessionToRevoke"
                     OnConfirmed="RevokeConfirmedAsync"
                     OnCancelled="RevokeCancelled" />

@code {
    [Parameter, EditorRequired] public ISettingsService SettingsService { get; set; } = default!;

    private SecuritySettings? _settings;
    private List<ActiveSession> _sessions = [];
    private bool _twoFactorEnabled;

    // Password fields
    private bool _passwordExpanded;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private bool _changingPassword;
    private string? _passwordMessage;
    private bool _passwordError;

    // Revoke dialog
    private bool _revokeDialogVisible;
    private ActiveSession? _sessionToRevoke;

    protected override async Task OnInitializedAsync()
    {
        _settings = await SettingsService.GetSecuritySettingsAsync();
        _sessions = _settings.Sessions;
        _twoFactorEnabled = _settings.TwoFactorEnabled;
    }

    private async Task ChangePasswordAsync()
    {
        _passwordMessage = null;

        if (string.IsNullOrWhiteSpace(_newPassword))
        {
            _passwordMessage = "New password cannot be empty.";
            _passwordError = true;
            return;
        }
        if (_newPassword != _confirmPassword)
        {
            _passwordMessage = "Passwords do not match.";
            _passwordError = true;
            return;
        }

        _changingPassword = true;
        try
        {
            await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
            _passwordMessage = "Password updated successfully!";
            _passwordError = false;
            _currentPassword = _newPassword = _confirmPassword = "";
        }
        catch (Exception ex)
        {
            _passwordMessage = $"Error: {ex.Message}";
            _passwordError = true;
        }
        finally
        {
            _changingPassword = false;
        }
    }

    private void PromptRevoke(ActiveSession session)
    {
        _sessionToRevoke = session;
        _revokeDialogVisible = true;
    }

    private async Task RevokeConfirmedAsync()
    {
        if (_sessionToRevoke is not null)
        {
            await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
            _sessions = _sessions.Where(s => s.Id != _sessionToRevoke.Id).ToList();
        }
        _revokeDialogVisible = false;
        _sessionToRevoke = null;
    }

    private void RevokeCancelled()
    {
        _revokeDialogVisible = false;
        _sessionToRevoke = null;
    }

    private static string FormatLastActive(DateTime dt)
    {
        var diff = DateTime.UtcNow - dt;
        if (diff.TotalMinutes < 1) return "Just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes}m ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        return $"{(int)diff.TotalDays}d ago";
    }
}

