@using sv_b932a6f7d888474f98128800617f0fba.Services

<div class="appearance-section">
    <h4 class="mb-4">Appearance Settings</h4>

    @if (_settings is null)
    {
        <p class="text-muted">Loading…</p>
        return;
    }

    <div class="row g-4">
        <div class="col-md-7">
            @* ── Theme ── *@
            <div class="card mb-4">
                <div class="card-body">
                    <h6 class="card-title mb-3">Theme</h6>
                    @foreach (var theme in _themes)
                    {
                        <div class="form-check form-check-inline">
                            <input class="form-check-input" type="radio" name="theme" id="theme-@theme"
                                   value="@theme" checked="@(_theme == theme)"
                                   @onchange="() => _theme = theme" />
                            <label class="form-check-label" for="theme-@theme">@theme</label>
                        </div>
                    }
                </div>
            </div>

            @* ── Font Size ── *@
            <div class="card mb-4">
                <div class="card-body">
                    <h6 class="card-title mb-3">Font Size</h6>
                    @foreach (var size in _fontSizes)
                    {
                        <div class="form-check form-check-inline">
                            <input class="form-check-input" type="radio" name="fontSize" id="fs-@size"
                                   value="@size" checked="@(_fontSize == size)"
                                   @onchange="() => _fontSize = size" />
                            <label class="form-check-label" for="fs-@size">@size</label>
                        </div>
                    }
                </div>
            </div>

            @* ── Language ── *@
            <div class="card mb-4">
                <div class="card-body">
                    <h6 class="card-title mb-3">Language</h6>
                    <select class="form-select" @bind="_language">
                        @foreach (var lang in _languages)
                        {
                            <option value="@lang">@lang</option>
                        }
                    </select>
                </div>
            </div>

            @* ── Compact Mode ── *@
            <div class="card mb-4">
                <div class="card-body d-flex justify-content-between align-items-center">
                    <div>
                        <h6 class="mb-1">Compact Mode</h6>
                        <span class="text-muted small">Reduce spacing and padding across the UI</span>
                    </div>
                    <div class="form-check form-switch mb-0">
                        <input class="form-check-input" type="checkbox" @bind="_compactMode" style="transform: scale(1.3);" />
                    </div>
                </div>
            </div>

            <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
                @(_saving ? "Saving…" : "Save")
            </button>
            @if (_message is not null)
            {
                <div class="alert alert-success mt-3 fade show">@_message</div>
            }
        </div>

        @* ── Live Preview ── *@
        <div class="col-md-5">
            <div class="card h-100">
                <div class="card-header fw-semibold">Live Preview</div>
                <div class="card-body preview-area @PreviewThemeClass" style="@PreviewFontStyle">
                    <div class="preview-nav mb-3 @(_compactMode ? "compact" : "")">
                        <span class="fw-bold">AppName</span>
                        <span class="float-end text-muted small">@_language</span>
                    </div>
                    <div class="preview-card @(_compactMode ? "compact" : "")">
                        <h6>Dashboard</h6>
                        <p class="mb-1">Welcome back! Here's your summary.</p>
                        <span class="badge bg-primary">3 new</span>
                        <span class="badge bg-secondary ms-1">12 tasks</span>
                    </div>
                    <div class="preview-card mt-2 @(_compactMode ? "compact" : "")">
                        <h6>Recent Activity</h6>
                        <ul class="mb-0 small ps-3">
                            <li>Updated profile photo</li>
                            <li>Completed onboarding</li>
                        </ul>
                    </div>
                </div>
            </div>
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public ISettingsService SettingsService { get; set; } = default!;

    private AppearanceSettings? _settings;
    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;
    private bool _saving;
    private string? _message;

    private static readonly string[] _themes = ["Light", "Dark", "System"];
    private static readonly string[] _fontSizes = ["Small", "Medium", "Large"];
    private static readonly string[] _languages = ["English", "Spanish", "French", "German", "Japanese", "Chinese"];

    private string PreviewThemeClass => _theme switch
    {
        "Dark" => "preview-dark",
        "System" => "preview-system",
        _ => "preview-light"
    };

    private string PreviewFontStyle => _fontSize switch
    {
        "Small" => "font-size: 0.8rem;",
        "Large" => "font-size: 1.15rem;",
        _ => "font-size: 0.95rem;"
    };

    protected override async Task OnInitializedAsync()
    {
        _settings = await SettingsService.GetAppearanceAsync();
        _theme = _settings.Theme;
        _fontSize = _settings.FontSize;
        _language = _settings.Language;
        _compactMode = _settings.CompactMode;
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _message = null;
        var updated = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(updated);
        _settings = updated;
        _message = "Appearance saved!";
        _saving = false;
    }
}

